new = '''  <div class="field"><label>Mata pelajaran</label><select name="subject" id="subjectSelect" required></select></div>\n  <div class="field full" id="customSubjectWrap" style="display:none"><label>Mata pelajaran custom</label><input name="customSubject" id="customSubjectInput" placeholder="Contoh: Teknik Instalasi Tenaga Listrik" disabled><small class="hint">Tulis nama mata pelajaran/kompetensi keahlian. BantuBeres akan menganalisis karakteristiknya sebelum membuat jawaban AI.</small></div>\n  <div class="field full"><label>Topik pembelajaran</label>'''
