old = '''function fillSubjects(){const l=$('#levelSelect').value,c=$('#classSelect').value;$('#subjectSelect').innerHTML=(SUBJECTS[l][c]||[]).map(s=>`<option>${esc(s)}</option>`).join('')}\n$('#levelSelect').onchange=fillClasses;$('#classSelect').onchange=fillSubjects;\n$('#projectForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.id='p_'+Date.now();d.createdAt=new Date().toISOString();d.journey=makeJourney(d);state.projects.push(d);state.activeProjectId=d.id;save('bbe_projects',state.projects);localStorage.setItem('bbe_active_project',d.id);$('#projectModal').classList.remove('open');toast('Proyek dibuat. Peta perjalanan sudah disiapkan.');nav('generator')};'''
new = '''function fillSubjects(){const l=$('#levelSelect').value,c=$('#classSelect').value;const base=SUBJECTS[l]?.[c]||[];$('#subjectSelect').innerHTML=base.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')+`<option value="__custom__">✦ Mata Pelajaran Custom</option>`;toggleCustomSubjectField()}\nfunction toggleCustomSubjectField(){const select=$('#subjectSelect'),wrap=$('#customSubjectWrap'),input=$('#customSubjectInput');if(!select||!wrap||!input)return;const active=select.value==='__custom__';wrap.style.display=active?'block':'none';input.disabled=!active;input.required=active;if(active){setTimeout(()=>input.focus(),0)}}\n$('#levelSelect').onchange=fillClasses;$('#classSelect').onchange=fillSubjects;$('#subjectSelect').onchange=toggleCustomSubjectField;\nasync function analyzeCustomSubject(subject,level,className,topic){const name=String(subject||'').trim();if(!name)throw new Error('Nama mata pelajaran custom belum diisi.');if(!hasCredential())throw new Error('Mata pelajaran custom membutuhkan koneksi AI untuk dianalisis terlebih dahulu.');const prompt=`Kamu adalah analis kurikulum dan pembelajaran Indonesia. Analisis mata pelajaran custom berikut SEBELUM generator pembelajaran menjawab. Jangan membuat dokumen pembelajaran dulu.\n\nMATA PELAJARAN: ${name}\nJENJANG: ${level}\nKELAS: ${className}\nTOPIK AWAL: ${topic||'-'}\n\nTentukan secara hati-hati:\n1. Identitas/jenis bidang studi yang paling mungkin dimaksud.\n2. Ruang lingkup dan fokus kompetensinya.\n3. Konsep, keterampilan, prosedur, alat, atau praktik yang lazim relevan.\n4. Istilah dan konteks yang harus dipakai AI agar jawaban tidak bergeser ke mapel umum lain.\n5. Karakter pembelajaran yang paling sesuai untuk jenjang tersebut.\n6. Hal yang belum dapat dipastikan dan tidak boleh dikarang sebagai standar resmi.\n7. Aturan konteks untuk generator: bagaimana seluruh output harus tetap spesifik terhadap mata pelajaran custom ini.\n\nJika nama mata pelajaran merupakan kompetensi keahlian SMK, pahami sebagai bidang keahlian/kompetensi vokasional dan sesuaikan analisis dengan praktik, prosedur kerja, alat, keselamatan kerja, dan dunia kerja bila memang relevan. Jangan mengarang CP, regulasi, kode kompetensi, atau standar industri tertentu. Kembalikan analisis ringkas namun substantif dalam Bahasa Indonesia.`;return await gemini(prompt,false)}\n$('#projectForm').onsubmit=async e=>{e.preventDefault();const form=e.target,submitter=form.querySelector('button[type="submit"],button.primary');if(submitter){submitter.disabled=true;submitter.textContent='⏳ Menganalisis mata pelajaran...'}try{const d=Object.fromEntries(new FormData(form));if(d.subject==='__custom__'){d.customSubject=String(d.customSubject||'').trim();if(!d.customSubject){toast('Isi nama mata pelajaran custom terlebih dahulu.','err');$('#customSubjectInput').focus();return}if(!hasCredential()){openCredential();return}toast('AI sedang menganalisis mata pelajaran custom...');d.subject=d.customSubject;d.subjectType='custom';d.subjectAnalysis=await analyzeCustomSubject(d.customSubject,d.level,d.class,d.topic)}else{d.subjectType='standard';d.subjectAnalysis=''}d.id='p_'+Date.now();d.createdAt=new Date().toISOString();d.journey=makeJourney(d);state.projects.push(d);state.activeProjectId=d.id;save('bbe_projects',state.projects);localStorage.setItem('bbe_active_project',d.id);localStorage.setItem('bbe_last_custom_subject',d.subjectType==='custom'?d.subject:'');$('#projectModal').classList.remove('open');toast(d.subjectType==='custom'?'Proyek dibuat setelah analisis mata pelajaran AI selesai.':'Proyek dibuat. Peta perjalanan sudah disiapkan.');nav('generator')}catch(err){toast('Analisis mata pelajaran gagal: '+err.message,'err')}finally{if(submitter){submitter.disabled=false;submitter.textContent='Buat proyek'}}};'''
if old not in s:
    raise SystemExit('project JS marker not found')
s = s.replace(old, new, 1)

old = '''function buildContext(p){return `PROYEK: ${p.name}\\nJENJANG: ${p.level}\\nKELAS: ${p.class}\\nMATA PELAJARAN: ${p.subject}\\nTOPIK: ${p.topic}\\nPERTEMUAN: ${p.meetings}\\nDURASI: ${p.duration}\\nKESULITAN SISWA: ${p.difficulty}\\nMETODE: ${p.method}\\nKARAKTER SISWA: ${p.studentProfile||'-'}\\nSUMBER DAYA: ${p.resources||'-'}\\nTARGET: ${p.goal||'-'}\\nINSTRUKSI PROYEK: ${p.instructions||'-'}\\nPERJALANAN: ${p.journey.map(j=>`Pertemuan ${j.n}: ${j.title} — ${j.focus}`).join(' | ')}`}'''
new = '''function buildContext(p){const customBlock=p.subjectType==='custom'?`\\n\\nANALISIS MATA PELAJARAN CUSTOM (WAJIB DIJADIKAN KONTEKS):\\n${p.subjectAnalysis||'Analisis belum tersedia; lakukan analisis mata pelajaran sebelum menghasilkan jawaban.'}\\n\\nATURAN MAPEL CUSTOM:\\n- Pertahankan mata pelajaran "${p.subject}" sebagai fokus utama.\\n- Gunakan istilah, konsep, keterampilan, prosedur, dan contoh yang benar-benar relevan dengan bidang tersebut.\\n- Jangan mengubahnya menjadi mata pelajaran umum hanya karena nama/istilahnya tidak umum.\\n- Jangan mengarang CP, TP, regulasi, kode kompetensi, atau standar resmi yang tidak dapat dipastikan.\\n- Jika ada bagian yang belum pasti, nyatakan asumsi atau bagian yang perlu diverifikasi guru.`:'';return `PROYEK: ${p.name}\\nJENJANG: ${p.level}\\nKELAS: ${p.class}\\nMATA PELAJARAN: ${p.subject}\\nTOPIK: ${p.topic}\\nPERTEMUAN: ${p.meetings}\\nDURASI: ${p.duration}\\nKESULITAN SISWA: ${p.difficulty}\\nMETODE: ${p.method}\\nKARAKTER SISWA: ${p.studentProfile||'-'}\\nSUMBER DAYA: ${p.resources||'-'}\\nTARGET: ${p.goal||'-'}\\nINSTRUKSI PROYEK: ${p.instructions||'-'}\\nPERJALANAN: ${p.journey.map(j=>`Pertemuan ${j.n}: ${j.title} — ${j.focus}`).join(' | ')}${customBlock}`}'''
if old not in s:
    raise SystemExit('buildContext marker not found')
s = s.replace(old, new, 1)

old = '''function generateTool(tool){if(!hasCredential()){openCredential();return}const p=getActiveProject();if(!p)return;const btn=$('#generateBtn');btn.disabled=true;'''
new = '''async function ensureCustomSubjectAnalysis(p){if(p?.subjectType!=='custom')return p?.subjectAnalysis||'';if(p.subjectAnalysis)return p.subjectAnalysis;if(!hasCredential()){openCredential();throw new Error('Hubungkan AI terlebih dahulu agar mata pelajaran custom dapat dianalisis.')}p.subjectAnalysis=await analyzeCustomSubject(p.subject,p.level,p.class,p.topic);save('bbe_projects',state.projects);return p.subjectAnalysis}\nasync function generateTool(tool){if(!hasCredential()){openCredential();return}const p=getActiveProject();if(!p)return;const btn=$('#generateBtn');btn.disabled=true;'''
