new = '''try{if(p.subjectType==='custom'&&!p.subjectAnalysis){$('#outputBox').innerHTML='<div class="loading"><div><div class="spinner"></div><p>AI sedang menganalisis mata pelajaran custom sebelum menyusun jawaban...</p></div></div>';await ensureCustomSubjectAnalysis(p);renderGenerator()}const q=collectQuestions(),extra=$('#extraInstruction')?.value||'';const text=await gemini(promptFor(tool,p,q,extra),false);'''
